* >Natural Source Code: EODPROM
* PROGRAM: EODPROM - END OF DAY PROMOTION PROCESSING
* DESCRIPTION: BATCH PROGRAM FOR DAILY PROMOTION MAINTENANCE
*              ACTIVATES/DEACTIVATES PROMOTIONS BY DATE
*              UPDATES USAGE COUNTS, GENERATES PERFORMANCE REPORT
* LIBRARY: RETAILCORE
* ADABAS FILE: 121 (PROMOTION)
* CREATED: 2008-02-15  S. MARTINEZ
* MODIFIED: 2014-08-22 - ADDED AUTO-DEACTIVATION
* MODIFIED: 2021-03-10 - ADDED PERFORMANCE METRICS
* -------------------------------------------------------
DEFINE DATA
LOCAL
  1 #TODAY                (D)
  1 #TOTAL-PROMOS         (N6)
  1 #ACTIVATED            (N6)
  1 #DEACTIVATED          (N6)
  1 #EXHAUSTED            (N6)
  1 #EXPIRING-SOON        (N6)
  1 #EXPIRE-WARN-DAYS     (N4)    INIT <7>
  1 #EXPIRE-WARN-DATE     (D)
*
  1 EPM-VIEW VIEW OF PROMOTION-FILE
    2 EPM-ID               (N8)
    2 EPM-NAME             (A40)
    2 EPM-STATUS           (A1)
    2 EPM-START-DATE       (D)
    2 EPM-END-DATE         (D)
    2 EPM-MAX-USES         (N6)
    2 EPM-CURRENT-USES     (N6)
END-DEFINE
*
MOVE *DATX TO #TODAY
*
* -------------------------------------------------------
* LOAD PROMOTION CONFIGURATION
* -------------------------------------------------------
1 #CFG-VALUE   (A80)
1 #CFG-NUM     (N11.2)
1 #CFG-DATE    (D)
1 #CFG-FLAG    (A1)
1 #CFG-FOUND   (A1)
*
CALLNAT 'CONFIGN' 'PROMO.EXPIRE.WARN.DAYS'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
IF #CFG-FOUND = 'Y'
  MOVE #CFG-NUM TO #EXPIRE-WARN-DAYS
END-IF
*
CALLNAT 'CONFIGN' 'PROMO.MAX.STACK'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
*
* VALIDATE AND FORMAT DATES
1 #DT-VALID   (A1)
1 #DT-ERR     (A60)
1 #DT-RESULT  (D)
1 #DT-STR     (A10)
1 #DT-NUM     (N5)
CALLNAT 'DATEU' 'FMT' #TODAY #TODAY 0 #DT-RESULT
  #DT-STR #DT-NUM #DT-VALID #DT-ERR
*
MOVE #TODAY TO #EXPIRE-WARN-DATE
ADD #EXPIRE-WARN-DAYS TO #EXPIRE-WARN-DATE (D)
*
* GET FISCAL PERIOD FOR REPORT
1 #FISCAL-PERIOD (N5)
1 #FISCAL-YEAR   (N5)
CALLNAT 'DATEU' 'FIS' #TODAY #TODAY #FISCAL-YEAR #DT-RESULT
  #DT-STR #FISCAL-PERIOD #DT-VALID #DT-ERR
*
WRITE 'RETAILCORE - END OF DAY PROMOTION PROCESSING'
WRITE '=============================================='
WRITE 'RUN DATE    :' #DT-STR
WRITE 'FISCAL YEAR :' #FISCAL-YEAR
WRITE 'FISCAL PERIOD:' #FISCAL-PERIOD
WRITE ' '
*
READ EPM-VIEW BY EPM-ID
  ADD 1 TO #TOTAL-PROMOS
*
  * AUTO-ACTIVATE SCHEDULED PROMOTIONS
  IF EPM-STATUS = 'I'
    IF EPM-START-DATE <= #TODAY AND EPM-END-DATE >= #TODAY
      GET EPM-VIEW *ISN (HOLD)
      MOVE 'A' TO EPM-STATUS
      UPDATE EPM-VIEW
      ADD 1 TO #ACTIVATED
      WRITE '  ACTIVATED:' EPM-NAME
    END-IF
  END-IF
*
  * AUTO-DEACTIVATE EXPIRED PROMOTIONS
  IF EPM-STATUS = 'A'
    IF EPM-END-DATE < #TODAY
      GET EPM-VIEW *ISN (HOLD)
      MOVE 'I' TO EPM-STATUS
      UPDATE EPM-VIEW
      ADD 1 TO #DEACTIVATED
      WRITE '  DEACTIVATED (EXPIRED):' EPM-NAME
    END-IF
  END-IF
*
  * AUTO-EXHAUST MAXED OUT PROMOTIONS
  IF EPM-STATUS = 'A' AND EPM-MAX-USES > 0
    IF EPM-CURRENT-USES >= EPM-MAX-USES
      GET EPM-VIEW *ISN (HOLD)
      MOVE 'X' TO EPM-STATUS
      UPDATE EPM-VIEW
      ADD 1 TO #EXHAUSTED
      WRITE '  EXHAUSTED:' EPM-NAME
    END-IF
  END-IF
*
  * WARN ABOUT EXPIRING SOON
  IF EPM-STATUS = 'A'
    IF EPM-END-DATE <= #EXPIRE-WARN-DATE
      ADD 1 TO #EXPIRING-SOON
    END-IF
  END-IF
*
  IF *COUNTER = 100
    END OF TRANSACTION
  END-IF
END-READ
*
END OF TRANSACTION
*
WRITE ' '
WRITE 'PROMOTION SUMMARY'
WRITE '================='
WRITE 'TOTAL PROMOTIONS    :' #TOTAL-PROMOS
WRITE 'AUTO-ACTIVATED      :' #ACTIVATED
WRITE 'AUTO-DEACTIVATED    :' #DEACTIVATED
WRITE 'AUTO-EXHAUSTED      :' #EXHAUSTED
WRITE 'EXPIRING IN' #EXPIRE-WARN-DAYS 'DAYS:' #EXPIRING-SOON
* -------------------------------------------------------
* VALIDATE PROMOTION PRICING THROUGH PRICING ENGINE
* -------------------------------------------------------
WRITE ' '
WRITE 'STEP 2: VALIDATING PROMOTION PRICING...'
1 #PROMO-PRICE-ERRORS (N6)
1 #PM-PRICE-VIEW VIEW OF PROMOTION-FILE
  2 PMV-ID          (N8)
  2 PMV-STATUS      (A1)
  2 PMV-DISCOUNT-PCT (N5.2)
  2 PMV-PRODUCT-ID  (N8)
*
READ #PM-PRICE-VIEW BY PMV-ID
  IF PMV-STATUS NE 'A'
    ESCAPE TOP
  END-IF
  IF PMV-PRODUCT-ID > 0
    * VALIDATE PRODUCT STILL EXISTS AND IS ACTIVE
    1 #PG-PROD-ID  (N8)
    1 #PG-SKU      (A15)
    1 #PG-PROD-DATA
      2 #PG-PD-ID        (N8)
      2 #PG-PD-SKU       (A15)
      2 #PG-PD-ITEM-NO   (A12)
      2 #PG-PD-NAME      (A60)
      2 #PG-PD-SHORT-DESC (A30)
      2 #PG-PD-LONG-DESC (A200)
      2 #PG-PD-STATUS    (A1)
      2 #PG-PD-TYPE      (A2)
      2 #PG-PD-BRAND     (A30)
      2 #PG-PD-MFGR      (A40)
      2 #PG-PD-UPC       (A13)
    1 #PG-CAT
      2 #PG-PC-DEPT      (A4)
      2 #PG-PC-CLASS     (A4)
      2 #PG-PC-SUBCLASS  (A4)
      2 #PG-PC-PATH      (A60)
    1 #PG-ATTR
      2 #PG-PA-COLOR     (A20)
      2 #PG-PA-SIZE      (A10)
      2 #PG-PA-WEIGHT    (N7.3)
      2 #PG-PA-PERISH    (A1)
      2 #PG-PA-HAZARD    (A1)
      2 #PG-PA-SEASON    (A1)
    1 #PG-PRICE
      2 #PG-PP-COST      (N9.2)
      2 #PG-PP-PRICE     (N9.2)
      2 #PG-PP-MSRP      (N9.2)
      2 #PG-PP-MIN       (N9.2)
      2 #PG-PP-TAX       (A4)
      2 #PG-PP-CURR      (A3)
    1 #PG-LIFECYCLE
      2 #PG-PL-INTRO     (D)
      2 #PG-PL-DISCO     (D)
      2 #PG-PL-CLEAR     (D)
      2 #PG-PL-LAST-SOLD (D)
    1 #PG-FOUND    (A1)
    1 #PG-ERR      (A60)
*
    MOVE PMV-PRODUCT-ID TO #PG-PROD-ID
    RESET #PG-SKU
    CALLNAT 'PRODGET' #PG-PROD-ID #PG-SKU #PG-PROD-DATA #PG-CAT
      #PG-ATTR #PG-PRICE #PG-LIFECYCLE #PG-FOUND #PG-ERR
    IF #PG-FOUND NE 'Y'
      ADD 1 TO #PROMO-PRICE-ERRORS
      CALLNAT 'LOGERR' 901 #PG-ERR 'W' 'EODPROM' *USER
    ELSE
      * CHECK THAT PROMO DISCOUNT DOESN'T BREACH MIN PRICE
      IF #PG-PP-MIN > 0
        1 #PROMO-PRICE (N9.2)
        COMPUTE #PROMO-PRICE = #PG-PP-PRICE
          - (#PG-PP-PRICE * PMV-DISCOUNT-PCT / 100)
        IF #PROMO-PRICE < #PG-PP-MIN
          ADD 1 TO #PROMO-PRICE-ERRORS
          1 #PRICE-ERR-MSG (A80)
          COMPRESS 'PROMO' PMV-ID 'BREACHES MIN PRICE FOR PROD'
            PMV-PRODUCT-ID INTO #PRICE-ERR-MSG
          CALLNAT 'LOGERR' 902 #PRICE-ERR-MSG 'W' 'EODPROM' *USER
        END-IF
      END-IF
    END-IF
  END-IF
  IF *COUNTER > 2000
    ESCAPE BOTTOM
  END-IF
END-READ
WRITE '  PROMOTION PRICING ERRORS:' #PROMO-PRICE-ERRORS
*
* -------------------------------------------------------
* CHECK INVENTORY FOR PROMOTED PRODUCTS
* -------------------------------------------------------
WRITE ' '
WRITE 'STEP 3: CHECKING INVENTORY FOR PROMOTED ITEMS...'
1 #INV-VALID     (A1)
1 #INV-ERR       (A60)
1 #INV-ON-HAND   (N8)
1 #INV-RESERVED  (N8)
1 #INV-AVAILABLE (N8)
1 #INV-LOW-COUNT (N6)
*
READ #PM-PRICE-VIEW BY PMV-ID
  IF PMV-STATUS NE 'A' OR PMV-PRODUCT-ID = 0
    ESCAPE TOP
  END-IF
  CALLNAT 'INVCHK' PMV-PRODUCT-ID ' ' 0 'S'
    #INV-ON-HAND #INV-RESERVED #INV-AVAILABLE
    #INV-VALID #INV-ERR
  IF #INV-VALID = 'Y' AND #INV-AVAILABLE < 10
    ADD 1 TO #INV-LOW-COUNT
  END-IF
  IF *COUNTER > 2000
    ESCAPE BOTTOM
  END-IF
END-READ
WRITE '  PROMOTED ITEMS LOW STOCK:' #INV-LOW-COUNT
*
WRITE ' '
WRITE 'PROMOTION SUMMARY'
WRITE '================='
WRITE 'TOTAL PROMOTIONS    :' #TOTAL-PROMOS
WRITE 'AUTO-ACTIVATED      :' #ACTIVATED
WRITE 'AUTO-DEACTIVATED    :' #DEACTIVATED
WRITE 'AUTO-EXHAUSTED      :' #EXHAUSTED
WRITE 'EXPIRING IN' #EXPIRE-WARN-DAYS 'DAYS:' #EXPIRING-SOON
WRITE 'PRICING ERRORS      :' #PROMO-PRICE-ERRORS
WRITE 'LOW STOCK ITEMS     :' #INV-LOW-COUNT
WRITE ' '
WRITE 'EOD PROMOTION PROCESSING COMPLETE'
*
* -------------------------------------------------------
* AUDIT AND LOG COMPLETION
* -------------------------------------------------------
CALLNAT 'AUDITN' 'PROM' 'EODPROM' 'U' 'BATCH'
  ' ' ' ' 'EOD PROMOTION PROCESSING COMPLETE'
*
1 #PROM-COMP-MSG (A80)
COMPRESS 'EODPROM: ACTIVATED=' #ACTIVATED
  ' DEACTIVATED=' #DEACTIVATED ' ERRORS=' #PROMO-PRICE-ERRORS
  INTO #PROM-COMP-MSG
CALLNAT 'LOGERR' 0 #PROM-COMP-MSG 'I' 'EODPROM' *USER
*
END
